"""PDF extraction, on real PDFs generated by the same library the application reads them with."""

import time

import pymupdf
import pytest

from app.modules.extraction.pdf import PdfRejected, extract_pdf


def make_pdf(pages: list[list[tuple[str, float]]]) -> bytes:
    """Each page is a list of (text, font size). Each text is a separate block."""
    document = pymupdf.open()
    for blocks in pages:
        page = document.new_page()
        y = 60.0
        for text, size in blocks:
            box = pymupdf.Rect(50, y, 545, y + 120)
            page.insert_textbox(box, text, fontsize=size, fontname="helv")
            y += 130
    data = document.tobytes()
    document.close()
    return data


def test_page_numbers_and_sections_are_kept():
    data = make_pdf(
        [
            [("3 Operations", 18), ("Le solde est disponible a tout moment.", 11)],
            [("3.2 Virements", 18), ("Au-dela de 10 000 MAD, un SMS est demande.", 11)],
        ]
    )
    result = extract_pdf(data, max_pages=10)
    assert result.page_count == 2
    assert not result.needs_ocr
    by_page = {segment.page: segment for segment in result.segments}
    assert by_page[1].section_path == "3 Operations"
    assert by_page[2].section_path == "3 Operations > 3.2 Virements"
    assert by_page[2].text == "Au-dela de 10 000 MAD, un SMS est demande."


def test_lines_of_a_paragraph_are_joined_so_an_amount_cannot_be_split():
    long_line = "Le plafond journalier reste applicable sur ce canal pour tous les clients " * 2
    data = make_pdf([[(long_line + "soit 10 000 MAD au total.", 11)]])
    segment = extract_pdf(data, max_pages=10).segments[0]
    assert "\n" not in segment.text
    assert "10 000 MAD" in segment.text


def test_a_word_cut_at_a_line_end_is_rejoined():
    document = pymupdf.open()
    page = document.new_page()
    page.insert_text((50, 100), "La vérifica-", fontsize=11)
    page.insert_text((50, 113), "tion est demandée pour ce virement de contrôle.", fontsize=11)
    data = document.tobytes()
    document.close()
    assert "vérification est demandée" in extract_pdf(data, max_pages=10).segments[0].text


def test_a_segment_never_spans_two_pages():
    text = "Paragraphe de contenu assez long pour remplir cette page de test. " * 3
    result = extract_pdf(make_pdf([[(text, 11)], [(text, 11)]]), max_pages=10)
    assert [segment.page for segment in result.segments] == [1, 2]


def test_a_page_without_text_is_reported_as_needing_ocr():
    document = pymupdf.open()
    document.new_page()
    data = document.tobytes()
    document.close()
    result = extract_pdf(data, max_pages=10)
    assert result.needs_ocr
    assert result.segments == []


def test_page_limit():
    with pytest.raises(PdfRejected, match="limite"):
        extract_pdf(make_pdf([[("a", 11)], [("b", 11)]]), max_pages=1)


def test_password_protected_pdf_is_refused():
    document = pymupdf.open()
    document.new_page().insert_text((50, 100), "secret")
    data = document.tobytes(encryption=pymupdf.PDF_ENCRYPT_AES_256, user_pw="x", owner_pw="y")
    document.close()
    with pytest.raises(PdfRejected, match="mot de passe"):
        extract_pdf(data, max_pages=10)


def test_garbage_after_a_valid_signature_is_refused():
    with pytest.raises(PdfRejected, match="illisible"):
        extract_pdf(b"%PDF-1.7 this is not really a pdf", max_pages=10)


def test_nfr003_fifty_page_pdf_is_extracted_in_under_thirty_seconds():
    paragraph = "Les virements superieurs au seuil font l'objet d'un controle renforce. " * 8
    data = make_pdf(
        [[(f"{n} Section", 16), (paragraph, 11), (paragraph, 11)] for n in range(1, 51)]
    )
    started = time.perf_counter()
    result = extract_pdf(data, max_pages=100)
    assert time.perf_counter() - started < 30
    assert result.page_count == 50
    assert {segment.page for segment in result.segments} == set(range(1, 51))
